{
  "name": "oh-my-msgcode",
  "version": "0.1.3",
  "description": "Inter-agent messaging plugin for OpenCode — agents in different sessions can send and receive messages",
  "type": "module",
  "main": "./dist/index.js",
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "test": "npm run build && node test-workspace/test-plugin.mjs && node test-workspace/test-e2e.mjs",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agent",
    "messaging",
    "inter-agent"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/GonGe1018/oh-my-msgcode.git"
  },
  "homepage": "https://github.com/GonGe1018/oh-my-msgcode",
  "bugs": {
    "url": "https://github.com/GonGe1018/oh-my-msgcode/issues"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.4.17"
  },
  "devDependencies": {
    "@types/node": "^22.15.3",
    "typescript": "^5.8.3"
  },
  "engines": {
    "node": ">=18"
  }
}
